/** 用户信息 / 未读数 / 待办数：优先真实接口，未登录或接口异常时静默回退设计稿静态数据 */
const mine = ref<PortalMineData>(SEED_MINE)
/**
 * 首屏加载态：仅当真正走真实接口（remote 模式 + 已登录）时为 true，
 * 先渲染骨架屏再填充真实数据，避免先显示静态种子（mock）再被真实数据替换的闪烁；
 * demo 模式直接展示静态数据，不进入骨架屏。仅在首次加载出现。
 */
const loading = ref(usePortalApi())
async function loadMine() {
  try { mine.value = await fetchMine() } catch { /* 保留静态数据 */ }
  finally { loading.value = false }
}
onShow(() => { void loadMine() })

